import{X,GitCompareArrows}from'lucide-react';import{Link}from'react-router-dom';import{useStore}from'../context/Store';import{products}from'../data/products';
export default function CompareBar(){const{compare,toggleCompare}=useStore();if(!compare.length)return null;const items=products.filter(p=>compare.includes(p.id));return <div className="compare-bar"><div className="container"><div className="compare-label"><GitCompareArrows/><span><b>Compare products</b><small>Select up to 4</small></span></div><div className="compare-items">{items.map(p=><div key={p.id}><img src={p.image}/><span>{p.name}</span><button onClick={()=>toggleCompare(p.id)}><X/></button></div>)}</div><Link to="/compare" className="btn dark">Compare now ({items.length})</Link></div></div>}
