import{useState}from'react';import{Link}from'react-router-dom';import{ArrowRight,ShieldCheck}from'lucide-react';import{getSiteContent}from'../data/siteConfig';
const linkPath=(x:string)=>({"About Us":"/about","Contact Us":"/contact","Distribution Process":"/how-it-works","All Products":"/shop","Customer Login":"/login","Apply for Account":"/apply","My Account":"/account","Quick Order":"/quick-order","Orders":"/account","Reorder Center":"/account","FAQs":"/faq","Contact Support":"/contact"} as Record<string,string>)[x]||'/'+x.toLowerCase().replaceAll(' & ','-').replaceAll(' ','-');
const groups:[string,string[]][]=[['Company',['About Us','Why Choose Us','Distribution Process','Contact Us']],['Shop',['All Products','Categories','Brands','New Arrivals','Best Sellers','Deals']],['Customer',['Customer Login','Apply for Account','My Account','Quick Order','Orders','Reorder Center']],['Help',['FAQs','Shipping & Delivery','Returns & Policies','Payment Information','Contact Support']]];
export default function Footer(){const[content]=useState(getSiteContent);const[email,setEmail]=useState('');const[ok,setOk]=useState(false);return <footer><section className="newsletter container"><div><span>MERIDIAN MARKET NOTES</span><h2>Wholesale intelligence,<br/>delivered with purpose.</h2></div><form onSubmit={e=>{e.preventDefault();if(email.includes('@'))setOk(true)}}>{ok?<p className="success">✓ You’re on the list. Watch your inbox.</p>:<><label htmlFor="newsletter">New arrivals, inventory updates and retail insights.</label><div><input id="newsletter" value={email} onChange={e=>setEmail(e.target.value)} type="email" placeholder="Business email address" required/><button aria-label="Subscribe"><ArrowRight/></button></div></>}</form></section><div className="footer-main container"><div className="footer-brand"><Link className="logo light" to="/"><b>MERIDIAN</b><span>SUPPLY CO.</span></Link><p>{content.footerDescription}</p><span className="wholesale"><ShieldCheck/> Wholesale only · Account approval required</span></div>{groups.map(([title,links])=><div className="footer-col" key={title}><h4>{title}</h4>{links.map(x=><Link key={x} to={linkPath(x)}>{x}</Link>)}</div>)}</div><div className="footer-bottom container"><p>© 2026 Meridian Supply Co. Demo company name and content.</p><div><Link to="/privacy-policy">Privacy</Link><Link to="/terms-conditions">Terms</Link><Link to="/trademark-disclaimer">Trademark Disclaimer</Link><Link to="/accessibility">Accessibility</Link><span className="social-mark" title="Configure the official profile in administration">LinkedIn</span><span className="social-mark" title="Configure the official profile in administration">Instagram</span></div></div></footer>}
